@Composable fun money(v:Double)=Text("B$%.2f".format(v))

class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{KadaiKuApp()}}}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun KadaiKuApp(){
    var tab by remember{mutableIntStateOf(0)}
    var products by remember{mutableStateOf(listOf(
        Product(name="Kek Coklat Premium",price=15.0,shop="Dapur Aisyah",category="Makanan",area="Gadong",image="🍰",sellerPhone="+673 7XX XXXX",sellerAddress="Gadong, Brunei-Muara"),
        Product(name="Perfume Oud",price=20.0,shop="Brunei Fragrance",category="Beauty",area="Kiulap",image="🧴",sellerPhone="+673 8XX XXXX",sellerAddress="Kiulap, Brunei-Muara"),
        Product(name="Baju Melayu",price=35.0,shop="Kedai Kita",category="Fashion",area="Bandar",image="👕",sellerPhone="+673 7XX XXXX",sellerAddress="Bandar Seri Begawan"),
        Product(name="Frozen Food Combo",price=12.0,shop="Mama's Frozen",category="Makanan",area="Tutong",image="🥟",sellerPhone="+673 8XX XXXX",sellerAddress="Tutong, Brunei")
    ))}
    var cart by remember{mutableStateOf(listOf<CartLine>())}
    var orders by remember{mutableStateOf(listOf<Order>())}
    var search by remember{mutableStateOf("")}
    var showSeller by remember{mutableStateOf(false)}
    var showAdd by remember{mutableStateOf(false)}
    var sellerProfile by remember{mutableStateOf(SellerProfile("Kedai Saya","",""))}
    val filtered=products.filter{search.isBlank()||it.name.contains(search,true)||it.shop.contains(search,true)||it.category.contains(search,true)}
    Scaffold(topBar={CenterAlignedTopAppBar(title={Text("KadaiKu 🇧🇳",fontWeight=FontWeight.Bold)})},bottomBar={NavigationBar{listOf("Home","Search","Cart (${cart.sumOf{it.qty}})","Profile").forEachIndexed{i,l->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={},label={Text(l)})}}}){pad->
        when(tab){
            0->Home(filtered,search,{search=it},{showSeller=true},{p->cart=addCart(cart,p)},Modifier.padding(pad))
            1->SearchPage(filtered,search,{search=it},{p->cart=addCart(cart,p)},Modifier.padding(pad))
            2->CartPage(cart,{p->cart=removeOne(cart,p)},{p->cart=addCart(cart,p)},{delivery,total->if(cart.isNotEmpty()){orders=orders+Order(lines=cart.map{it.copy()},delivery=delivery,total=total);cart=listOf();tab=3}},Modifier.padding(pad))
            else->ProfilePage(orders,{showSeller=true},Modifier.padding(pad))
        }
    }
    if(showSeller)SellerSheet(onClose={showSeller=false},onAdd={showAdd=true},products=products,orders=orders,profile=sellerProfile,onProfileChange={sellerProfile=it},onDelete={id->products=products.filterNot{it.id==id}})
    if(showAdd)AddProductDialog(sellerProfile=sellerProfile,onDismiss={showAdd=false},onSave={name,price,cat,area,image->products=products+Product(name=name,price=price,shop=sellerProfile.shop.ifBlank{"Kedai Saya"},category=cat,area=area,image=image,sellerPhone=sellerProfile.phone,sellerAddress=sellerProfile.address);showAdd=false})
}

fun addCart(c:List<CartLine>,p:Product):List<CartLine>{val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0)x[i]=x[i].copy(qty=x[i].qty+1)else x.add(CartLine(p,1));return x}
fun removeOne(c:List<CartLine>,p:Product):List<CartLine>{val x=c.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0){if(x[i].qty>1)x[i]=x[i].copy(qty=x[i].qty-1)else x.removeAt(i)};return x}

@Composable fun ProductImage(image:String,modifier:Modifier=Modifier){if(image.startsWith("content://")||image.startsWith("file://")){Image(painter=rememberAsyncImagePainter(Uri.parse(image)),contentDescription="Product image",modifier=modifier,contentScale=ContentScale.Crop)}else{Box(modifier=modifier.background(Color(0xFFF2F0FA)),contentAlignment=Alignment.Center){Text(image.ifBlank{"🛍️"},style=MaterialTheme.typography.headlineLarge)}}}

