@Composable fun LiveOrderCard(order:Order){var stage by remember(order.id){mutableIntStateOf(0)};var showTracking by remember(order.id){mutableStateOf(false)};val deliveryStages=listOf("Order diterima","Sedang disediakan","Rider mengambil","Dalam perjalanan","Sampai");val pickupStages=listOf("Order diterima","Sedang disediakan","Sedia untuk pickup","Selesai");val stages=if(order.delivery=="Pickup")pickupStages else deliveryStages;LaunchedEffect(order.id){while(stage<stages.lastIndex){delay(7000);stage++}};val eta=when{order.delivery=="Pickup"&&stage<2->"± 10 min";order.delivery=="Pickup"->"Boleh ambil sekarang";stage==0->"± 25 min";stage==1->"± 20 min";stage==2->"± 15 min";stage==3->"± 7 min";else->"Sudah sampai"};val statusColor=when(stage){0->Color(0xFF6A1B9A);1->Color(0xFFF57C00);2->Color(0xFF00897B);3->Color(0xFF1E88E5);else->Color(0xFF2E7D32)};Card(shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(containerColor=Color.White),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("Order #${order.id}",fontWeight=FontWeight.Bold);Text("${order.delivery} • ${order.lines.sumOf{it.qty}} item",color=Color.Gray)};Text("LIVE",color=Color.White,fontWeight=FontWeight.Bold,modifier=Modifier.clip(RoundedCornerShape(50)).background(Color(0xFFE53935)).padding(horizontal=10.dp,vertical=4.dp))};Spacer(Modifier.height(12.dp));Text(stages[stage],fontWeight=FontWeight.ExtraBold,color=statusColor,style=MaterialTheme.typography.titleMedium);Text("Anggaran: $eta");Spacer(Modifier.height(10.dp));LinearProgressIndicator(progress={(stage+1).toFloat()/stages.size.toFloat()},modifier=Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(50)));Spacer(Modifier.height(10.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Rider: Ahmad");Text("B$%.2f".format(order.total),fontWeight=FontWeight.Bold)};order.lines.firstOrNull()?.product?.let{p->Spacer(Modifier.height(8.dp));Text("Seller: ${p.shop}",fontWeight=FontWeight.Bold);Text("📞 ${p.sellerPhone}");Text("🏠 ${p.sellerAddress}")};Spacer(Modifier.height(8.dp));OutlinedButton(onClick={showTracking=!showTracking},modifier=Modifier.fillMaxWidth()){Text(if(showTracking)"Tutup Tracking" else "📍 Live Tracking")};if(showTracking){Spacer(Modifier.height(8.dp));Card(colors=CardDefaults.cardColors(containerColor=Color(0xFFE3F2FD)),shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(12.dp)){Text("Live rider location",fontWeight=FontWeight.Bold);Text("🛵 Rider sedang bergerak menuju lokasi buyer.");Text("Demo GPS tracking untuk testing version.",style=MaterialTheme.typography.bodySmall,color=Color.Gray)}}}}}}

fun startOfWeek(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_WEEK,firstDayOfWeek);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfMonth(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_MONTH,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}
fun startOfYear(now:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=now;set(Calendar.DAY_OF_YEAR,1);set(Calendar.HOUR_OF_DAY,0);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};return c.timeInMillis}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun SellerSheet(onClose:()->Unit,onAdd:()->Unit,products:List<Product>,orders:List<Order>,profile:SellerProfile,onProfileChange:(SellerProfile)->Unit,onDelete:(String)->Unit){var shop by remember(profile){mutableStateOf(profile.shop)};var phone by remember(profile){mutableStateOf(profile.phone)};var address by remember(profile){mutableStateOf(profile.address)};val now=System.currentTimeMillis();val weekOrders=orders.filter{it.createdAt>=startOfWeek(now)};val monthOrders=orders.filter{it.createdAt>=startOfMonth(now)};val yearOrders=orders.filter{it.createdAt>=startOfYear(now)};ModalBottomSheet(onDismissRequest=onClose){LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Seller Dashboard",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{Card(colors=CardDefaults.cardColors(containerColor=Color(0xFFF3E5F5)),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(14.dp)){Text("Seller Contact",fontWeight=FontWeight.Bold);OutlinedTextField(shop,{shop=it},label={Text("Nama kedai")},modifier=Modifier.fillMaxWidth());OutlinedTextField(phone,{phone=it},label={Text("No. telefon")},modifier=Modifier.fillMaxWidth());OutlinedTextField(address,{address=it},label={Text("Alamat kedai")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));Button(onClick={onProfileChange(SellerProfile(shop,phone,address))},modifier=Modifier.fillMaxWidth(),enabled=phone.isNotBlank()&&address.isNotBlank()){Text("Simpan Contact")}}}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){StatCard("Minggu",weekOrders.size,weekOrders.sumOf{it.total},Modifier.weight(1f));StatCard("Bulan",monthOrders.size,monthOrders.sumOf{it.total},Modifier.weight(1f));StatCard("Tahun",yearOrders.size,yearOrders.sumOf{it.total},Modifier.weight(1f))}};item{Button(onClick=onAdd,modifier=Modifier.fillMaxWidth(),enabled=profile.phone.isNotBlank()&&profile.address.isNotBlank()){Text("+ Tambah Produk")}};item{Text("Produk saya",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold)};val mine=products.filter{it.shop==profile.shop};if(mine.isEmpty())item{Text("Belum ada produk")};else items(mine){p->Card(Modifier.fillMaxWidth()){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){ProductImage(p.image,Modifier.size(54.dp).clip(RoundedCornerShape(12.dp)));Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(p.name,fontWeight=FontWeight.Bold);money(p.price)};TextButton(onClick={onDelete(p.id)}){Text("Padam")}}}};item{Text("Recent Orders",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold)};if(orders.isEmpty())item{Text("Belum ada order")};else items(orders.takeLast(5).reversed()){o->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("#${o.id}",fontWeight=FontWeight.Bold);Text("${o.delivery} • ${o.lines.sumOf{it.qty}} item");money(o.total)}}}};item{Spacer(Modifier.height(30.dp))}}}}

